enum Light { RED, YELLOW, GREEN }
public class Main {
    public static void main(String[] args) {
        Light l = Light.YELLOW;
        switch (l) {
            case RED:
                System.out.print("stop ");
            case YELLOW:
                System.out.print("slow ");
            case GREEN:
                System.out.print("go ");
                break;
            default:
                System.out.print("? ");
        }
    }
}

enum Level { LOW, MEDIUM, HIGH }
public class Main {
    public static void main(String[] args) {
        Level a = Level.LOW;
        System.out.print((a.compareTo(Level.HIGH) < 0) + " ");
        System.out.print((Level.valueOf("MEDIUM") == Level.MEDIUM) + " ");
        System.out.print(Level.HIGH.name().equals(Level.HIGH.toString()) + " ");
        System.out.print(Level.values()[2]);
    }
}

enum Op {
    PLUS {
        int apply(int a, int b) { return a + b; }
    },
    MINUS,
    TIMES {
        int apply(int a, int b) { return a * b; }
    };
    abstract int apply(int a, int b);
}
public class Main {
    public static void main(String[] args) {
        System.out.println(Op.PLUS.apply(2, 3) + Op.TIMES.apply(2, 3));
    }
}

enum Planet {
